// Validation, filtrage (médiane glissante sur 3 mesures) et enrichissement de la télémétrie brute.
// Entrée : fw/raw/<code>/telemetry  ->  Sortie : floodwatch/stations/<code>/telemetry
const code = msg.topic.split('/')[2];
let data;
try { data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { node.warn(`JSON invalide de ${code}`); return null; }
const cfg = (flow.get('configs') || {})[code] || {};
const sensorHeight = Number(cfg.sensorHeightCm || 30);
const level = Number(data.levelCm);
const rain = Math.min(1, Math.max(0, Number(data.rain || 0)));
const plausible = Number.isFinite(level) && level >= -2 && level <= sensorHeight + 2 && data.sensorOk !== false;
const out = { levelCm: null, rain: rain, sensorOk: plausible, gw: env.get('GATEWAY_ID') || 'gw-01', seq: data.seq };
if (plausible) {
    const hist = flow.get('hist') || {};
    const h = (hist[code] || []).concat([level]).slice(-3);
    hist[code] = h; flow.set('hist', hist);
    const sorted = [...h].sort((a, b) => a - b);
    out.levelCm = Math.round(sorted[Math.floor(sorted.length / 2)] * 100) / 100;
    out.rawLevelCm = level;
} else {
    out.levelCm = Number.isFinite(level) ? level : -1;
    node.warn(`Mesure rejetée pour ${code} : ${data.levelCm}`);
}
node.status({ fill: plausible ? 'green' : 'red', shape: 'dot', text: `${code} ${out.levelCm} cm` });
return { topic: `floodwatch/stations/${code}/telemetry`, payload: JSON.stringify(out), qos: 1 };

// Mémorise la configuration retenue (seuils) de chaque station pour la validation locale.
const code = msg.topic.split('/')[2];
try {
    const configs = flow.get('configs') || {};
    configs[code] = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    flow.set('configs', configs);
    node.status({ fill: 'blue', shape: 'ring', text: `config ${code}` });
} catch (e) { node.warn('config illisible : ' + e.message); }
return null;

// Dernier contact de chaque station (tout message montant).
const parts = msg.topic.split('/');
const code = parts[0] === 'fw' ? parts[2] : parts[2];
const seen = flow.get('lastSeen') || {};
seen[code] = Date.now();
flow.set('lastSeen', seen);
return null;

// Détection locale des stations muettes (aucun message depuis 45 s = 3 messages de vie manqués).
const LIMIT = Number(env.get('MUTE_AFTER_SEC') || 45) * 1000;
const seen = flow.get('lastSeen') || {};
const muted = flow.get('muted') || {};
const gw = env.get('GATEWAY_ID') || 'gw-01';
const now = Date.now();
const out = [];
for (const [code, t] of Object.entries(seen)) {
    const silent = now - t > LIMIT;
    if (silent && !muted[code]) {
        muted[code] = true;
        out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1,
                   payload: JSON.stringify({ type: 'station_mute', station: code, silentSec: Math.round((now - t) / 1000), ts: now }) });
    } else if (!silent && muted[code]) {
        delete muted[code];
        out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1,
                   payload: JSON.stringify({ type: 'station_back', station: code, ts: now }) });
    }
}
flow.set('muted', muted);
node.status({ fill: Object.keys(muted).length ? 'red' : 'green', shape: 'dot',
              text: `${Object.keys(seen).length} station(s), ${Object.keys(muted).length} muette(s)` });
return [out];

// Message de vie de la passerelle (toutes les 5 min).
const gw = env.get('GATEWAY_ID') || 'gw-01';
const start = context.get('start') || Date.now();
context.set('start', start);
return { topic: `floodwatch/gateways/${gw}/events`, qos: 1,
         payload: JSON.stringify({ type: 'gateway_alive', uptimeSec: Math.round((Date.now() - start) / 1000), ts: Date.now() }) };
